from ledger.reports import trial_balance, income_statement


def init_db(args) -> None:
    """Initialize the database."""
    _db_init_db(args.db)
    print("Database initialized.")


def add_account(args) -> None:
    """Add a new account after validation."""
    try:
        _add_account(args.db, args.name, args.type)
        print(f"Account '{args.name}' added (type={args.type}).")
    except ValueError as e:
        print(str(e), file=sys.stderr)
        sys.exit(1)


def list_accounts(args) -> None:
    """List all accounts."""
    accounts = _list_accounts(args.db)
    if not accounts:
        print("No accounts found.")
        return
    for acct in accounts:
        print(f"{acct['name']}\t{acct['type']}")


def add_transaction(args) -> None:
    """Add a balanced transaction after validating accounts and amounts."""
    # Parse debit entries: "ACCOUNT:AMOUNT"
    debits = []
    if args.debit:
        for entry in args.debit:
            try:
                account_name, amount_str = entry.rsplit(":", 1)
                amount = Decimal(amount_str)
                debits.append((account_name, amount))
            except (ValueError, InvalidOperation):
                print(f"Invalid debit format: {entry}", file=sys.stderr)
                sys.exit(1)

    # Parse credit entries: "ACCOUNT:AMOUNT"
    credits = []
    if args.credit:
        for entry in args.credit:
            try:
                account_name, amount_str = entry.rsplit(":", 1)
                amount = Decimal(amount_str)
                credits.append((account_name, amount))
            except (ValueError, InvalidOperation):
                print(f"Invalid credit format: {entry}", file=sys.stderr)
                sys.exit(1)

    # Validate amounts are strictly positive
    for account_name, amount in debits:
        if amount <= 0:
            print(
                f"Debit amount must be positive, got {amount} for '{account_name}'",
                file=sys.stderr,
            )
            sys.exit(1)

    for account_name, amount in credits:
        if amount <= 0:
            print(
                f"Credit amount must be positive, got {amount} for '{account_name}'",
                file=sys.stderr,
            )
            sys.exit(1)

    # Validate all accounts exist
    for account_name, _ in debits + credits:
        acct = get_account(args.db, account_name)
        if acct is None:
            print(f"Unknown account: {account_name}", file=sys.stderr)
            sys.exit(1)

    # Check balanced
    total_debits = sum(amount for _, amount in debits)
    total_credits = sum(amount for _, amount in credits)
    if total_debits != total_credits:
        print(
            f"Transaction not balanced: debits={total_debits}, credits={total_credits}",
            file=sys.stderr,
        )
        sys.exit(1)

    # Build lines for insert_transaction (uses transaction_lines table)
    lines = []
    for account_name, amount in debits:
        lines.append((account_name, "debit", amount))
    for account_name, amount in credits:
        lines.append((account_name, "credit", amount))

    desc = args.desc or ""
    txn_id = insert_transaction(args.db, args.date, desc, lines)
    print(f"Transaction added (id={txn_id}).")


def list_transactions(args) -> None:
    """List transactions with optional date range filter."""
    from ledger.transactions import list_transactions as _list_txns

    from_date = getattr(args, "from_date", None)
    to_date = getattr(args, "to", None)

    txns = _list_txns(args.db, from_date=from_date or None, to_date=to_date or None)
    for txn in txns:
        print(f"{txn['id']}\t{txn['date']}\t{txn['description']}")


def get_balance(args) -> None:
    """Get the balance of an account, optionally as of a date."""
    as_of = None
    if args.as_of:
        try:
            as_of = datetime.strptime(args.as_of, "%Y-%m-%d").date()
        except ValueError:
            print(f"Invalid date format for --as-of: {args.as_of}", file=sys.stderr)
            sys.exit(1)

    balance = compute_balance(args.db, args.account, as_of)
    print(balance)


def trial_balance_report(args) -> None:
    """Generate a trial-balance report."""
    as_of = None
    if args.as_of:
        try:
            as_of = datetime.strptime(args.as_of, "%Y-%m-%d").date()
        except ValueError:
            print(f"Invalid date format for --as-of: {args.as_of}", file=sys.stderr)
            sys.exit(1)

    rows = trial_balance(args.db, as_of)
    total_debits = Decimal("0")
    total_credits = Decimal("0")

    for name, side, amount in rows:
        print(f"{name}\t{side}\t{amount}")
        if side == "debit":
            total_debits += amount
        else:
            total_credits += amount

    print(f"Total\tdebit\t{total_debits}")
    print(f"Total\tcredit\t{total_credits}")


def income_statement_report(args) -> None:
    """Generate an income-statement report."""
    try:
        from_date = datetime.strptime(args.from_date, "%Y-%m-%d").date()
        to_date = datetime.strptime(args.to, "%Y-%m-%d").date()
    except (ValueError, TypeError):
        print("Invalid date format. Use YYYY-MM-DD.", file=sys.stderr)
        sys.exit(1)

    total_income, total_expenses, net = income_statement(
        args.db, from_date, to_date
    )

    print(f"Income\t{total_income}")
    print(f"Expenses\t{total_expenses}")
    print(f"Net Income\t{net}")


